describe('File Upload Button', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should disable the upload button while a file is uploading', () => {
        const fileName = 'test-file.txt'; // Replace with an actual test file name
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.get('button.upload-button').should('be.disabled'); // Assuming the button has a class 'upload-button'
            cy.intercept('POST', '/upload-endpoint', { statusCode: 200 }).as('fileUpload');
            cy.get('button.upload-button').click();
            cy.wait('@fileUpload');
            cy.get('button.upload-button').should('not.be.disabled');
        });
    });

    it('should not allow multiple uploads at the same time', () => {
        const fileName = 'test-file.txt'; // Replace with an actual test file name
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.get('button.upload-button').should('be.disabled');
            cy.get('input[type="file"]').attachFile(fileName); // Attempt to upload another file
            cy.get('button.upload-button').should('be.disabled'); // Button should still be disabled
        });
    });
});
